INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(28, 'koKR', 'Próba jeziora', 'W ramach pierwszej próby przeszukaj głębiny Jeziora Elune\'ara i odnajdź błyskotkę z kapliczki. Szybko się rozpada, więc czym prędzej zanieś ją do Kapliczki Remulosa. Użyj błyskotki przy kapliczce, a potem porozmawiaj z Tajarri – to jedna z najbardziej zaufanych strażniczek Gaju Luny.$B$BNa wykonanie zadania masz ograniczony czas i możliwe, że będziesz rywalizować z innymi druidami, którzy również szukają błyskotek. Kluczem do sukcesu będzie zręczność umysłu i ciała.$B$BPowodzenia, $N.', 'Odnajdź błyskotkę z kapliczki w Jeziorze Elune\'ara i zanieś ją do Kapliczki Remulosa w północno-zachodniej części Gaju Luny. Na miejscu użyj błyskotki z kapliczki.$B$BAby ukończyć próbę, musisz potem porozmawiać z Tajarri przy kapliczce.', 'Ukończ próbę jeziora.', 'Wróć do Tajarri przy Kapliczce Remulosa w Gaju Luny.', '', '', '', '', 0),
(29, 'koKR', 'Próba jeziora', 'W ramach pierwszej próby przeszukaj głębiny Jeziora Elune\'ara i odnajdź błyskotkę z kapliczki. Szybko się rozpada, więc czym prędzej zanieś ją do Kapliczki Remulosa. Użyj błyskotki przy kapliczce, a potem porozmawiaj z Tajarri – to jedna z najbardziej zaufanych strażniczek Gaju Luny.$B$BNa wykonanie zadania masz ograniczony czas i możliwe, że będziesz rywalizować z innymi druidami, którzy również szukają błyskotek. Kluczem do sukcesu będzie zręczność umysłu i ciała.$B$BPowodzenia, $N.', 'Odnajdź błyskotkę z kapliczki w Jeziorze Elune\'ara i zanieś ją do Kapliczki Remulosa w północno-zachodniej części Gaju Luny. Na miejscu użyj błyskotki z kapliczki.$B$BAby ukończyć próbę, musisz potem porozmawiać z Tajarri przy kapliczce.', 'Ukończ próbę jeziora.', 'Wróć do Tajarri przy Kapliczce Remulosa w Gaju Luny.', '', '', '', '', 0),
(30, 'koKR', 'Próba lwa morskiego', 'W ramach drugiej próby potrzebne ci będą dwie połówki, z których składa się Wisior lwa morskiego. Jedna czerpie moc ze zwinności, z jaką lew morski sunie przez wodę, druga z jego niezwykłej wytrzymałości. Druidzi w równym stopniu czerpią z obu tych cech, by przybrać postać morską.$B$BPorozmawiaj z mieszkańcami Gaju Luny, aby dowiedzieć się, gdzie mogą leżeć te części, i przynieś je tutaj, by je połączyć. Gdy wisior będzie gotowy, zanieś go Dendrite\'owi Gwiezdnemu Płomieniowi.', 'Odnajdź połowę wisiora wodnej zręczności i połówkę wisiora wodnej wytrzymałości. Porozmawiaj z mieszkańcami Gaju Luny, aby zdobyć wskazówki, gdzie mogą się znajdować.$B$BZłóż Wisior lwa morskiego z dwóch połówek. Musisz w tym celu znajdować się w pobliżu Kapliczki Remulosa.$B$BZanieś złożony wisior Dendrite\'owi Gwiezdnemu Płomieniowi w wiosce Nocny Azyl w Gaju Luny.', '', 'Wróć do Dendrite\'a Gwiezdnego Płomienia w Nocnym Azylu w Gaju Luny.', '', '', '', '', 0),
(272, 'koKR', 'Próba lwa morskiego', 'W ramach drugiej próby potrzebne ci będą dwie połówki, z których składa się Wisior lwa morskiego. Jedna czerpie moc ze zwinności, z jaką lew morski sunie przez wodę, druga z jego niezwykłej wytrzymałości. Druidzi w równym stopniu czerpią z obu tych cech, by przybrać postać morską.$B$BPorozmawiaj z mieszkańcami Gaju Luny, aby dowiedzieć się, gdzie mogą leżeć te części, i przynieś je tutaj, by je połączyć. Gdy wisior będzie gotowy, zanieś go Dendrite\'owi Gwiezdnemu Płomieniowi.', 'Odnajdź połowę wisiora wodnej zręczności i połówkę wisiora wodnej wytrzymałości. Porozmawiaj z mieszkańcami Gaju Luny, aby zdobyć wskazówki, gdzie mogą się znajdować.$B$BZłóż Wisior lwa morskiego z dwóch połówek. Musisz w tym celu znajdować się w pobliżu Kapliczki Remulosa.$B$BZanieś złożony wisior Dendrite\'owi Gwiezdnemu Płomieniowi w wiosce Nocny Azyl w Gaju Luny.', '', 'Wróć do Dendrite\'a Gwiezdnego Płomienia w Nocnym Azylu w Gaju Luny.', '', '', '', '', 0),
(1185, 'koKR', 'Pod chityną było...', '', '', '', '', '', '', '', '', 0),
(5526, 'koKR', 'Odłamki spaczonego pnącza', 'Teraz przyda się twoja znajomość Eldre\'Thalas – Srogomłotów – w Feralas, $N. We wschodniej części zrujnowanego miasta Alzzin Kształtujący Dzicz roztoczył swoje splugawione panowanie. Udaj się tam czym prędzej i stawiaj czoła wszelkim wyzwaniom, jakie na ciebie czekają.$B$BOwoc Płodności, teraz spaczony jako spaczone pnącze, powinien znajdować się blisko Alzzina. Gdy Alzzin padnie, pochwyć tyle esencji spaczonego pnącza, ile zdołasz. Zapieczętuj ją w relikwiarzu i przynieś mi.$B$BPowodzenia i niech Cenarius doda ci chyżości.', 'Odnajdź spaczone pnącze w Srogomłotach i zdobądź jego odłamek. Najpewniej zdobędziesz go dopiero po śmierci Alzzina Kształtującego Dzicz. Użyj Relikwiarza czystości, aby bezpiecznie zapieczętować w nim odłamek, i zanieś go Rabine\'owi Saturnie w Nocnym Azylu w Gaju Luny.', '', 'Wróć do Rabine\'a Saturny w Nocnym Azylu w Gaju Luny.', '', '', '', '', 0),
(5527, 'koKR', 'Relikwiarz czystości', 'Pierwszym krokiem jest znalezienie pojemnika, który pomieści niezwykle splugawioną substancję tak, by nie zaszkodziła temu, kto go niesie. Znam tylko jeden rodzaj naczynia, które mogłoby pomieścić coś tak plugawego jak spaczone pnącze: relikwiarz czystości.$B$BGłęboko na pustkowiach Silithusu leżą pozostałości nocnoelfiej wioski zwanej Południowym Wiatrem. Wiem, że wiele, wiele lat temu był tam jeden taki relikwiarz. Jeśli mamy odnieść sukces, musisz przeczesać te ruiny w nadziei, że go odzyskasz.', 'Udaj się do Silithusu i poszukaj relikwiarza czystości w ruinach Osady Południowego Wiatru. Jeśli uda ci się go znaleźć, wróć z nim do Rabine\'a Saturny w Nocnym Azylu w Gaju Luny.', '', 'Wróć do Rabine\'a Saturny w Nocnym Azylu w Gaju Luny.', '', '', '', '', 0),
(5929, 'koKR', 'Duch Wielkiego Niedźwiedzia', 'W północno-zachodniej części Gaju Luny mieszka mądra i szlachetna istota, którą nazywamy Duchem Wielkiego Niedźwiedzia. Dla wszystkich druidów był nauczycielem i przewodnikiem ku pierwszemu prawdziwemu, naturalnemu zrozumieniu niedźwiedzia. Każdy druid w pewnym momencie szuka mądrości ducha i ty nie będziesz wyjątkiem.$B$BUdaj się teraz do Ducha Wielkiego Niedźwiedzia i naucz się tego, czego zechce cię nauczyć. Gdy będzie z ciebie zadowolony, wróć do mnie, tutaj, do Nocnego Azylu. Wtedy zobaczymy, czy naprawdę $gprzyswoiłeś:przyswoiłaś; sobie jego nauki.', 'Odszukaj Ducha Wielkiego Niedźwiedzia w północno-zachodniej części Gaju Luny i dowiedz się, czym zechce się z tobą podzielić na temat natury niedźwiedzia. Następnie wróć do Dendrite\'a Gwiezdnego Płomienia w Nocnym Azylu w Gaju Luny.', 'Odszukaj Ducha Wielkiego Niedźwiedzia i dowiedz się, czym zechce się z tobą podzielić na temat natury niedźwiedzia.', 'Wróć do Dendrite\'a Gwiezdnego Płomienia w Nocnym Azylu w Gaju Luny.', '', '', '', '', 0),
(5930, 'koKR', 'Duch Wielkiego Niedźwiedzia', 'W północno-zachodniej części Gaju Luny mieszka mądra i szlachetna istota, którą nazywamy Duchem Wielkiego Niedźwiedzia. Dla wszystkich druidów był nauczycielem i przewodnikiem ku pierwszemu prawdziwemu, naturalnemu zrozumieniu niedźwiedzia. Każdy druid w pewnym momencie szuka mądrości ducha i ty nie będziesz wyjątkiem.$B$BUdaj się teraz do Ducha Wielkiego Niedźwiedzia i naucz się tego, czego zechce cię nauczyć. Gdy będzie z ciebie zadowolony, wróć do mnie, tutaj, do Nocnego Azylu. Wtedy zobaczymy, czy naprawdę $gprzyswoiłeś:przyswoiłaś; sobie jego nauki.', 'Odszukaj Ducha Wielkiego Niedźwiedzia w północno-zachodniej części Gaju Luny i dowiedz się, czym zechce się z tobą podzielić na temat natury niedźwiedzia. Następnie wróć do Dendrite\'a Gwiezdnego Płomienia w Nocnym Azylu w Gaju Luny.', 'Odszukaj Ducha Wielkiego Niedźwiedzia i dowiedz się, czym zechce się z tobą podzielić na temat natury niedźwiedzia.', 'Wróć do Dendrite\'a Gwiezdnego Płomienia w Nocnym Azylu w Gaju Luny.', '', '', '', '', 0),
(6845, 'koKR', 'Odkrywanie dawnych sekretów', 'W każdym razie zajrzyj do mnie niedługo... to znaczy, jeśli chcesz wiedzieć, co tu było. Jak tylko się dowiem, co to jest, i jeśli to faktycznie książka, chętnie się z tobą tą wiedzą podzielę.$B$BA tymczasem zajrzyj do matki kwoki tego małego niedźwiedziego obozu, Rabine\'a. Na pewno będzie chciał wiedzieć, jakie szalone numery $gwyczyniałeś:wyczyniałaś;. Nigdy nie każ matce kwoce czekać, $N... chyba że chcesz zostać $goblany:oblana; miodem.$B$BZdarzało się, uwierz mi.', 'Porozmawiaj z Rabine\'em Saturną w wiosce Nocny Azyl w Gaju Luny.', '', '', '', '', '', '', 0),
(8446, 'koKR', 'Spowity koszmarem', 'Z tego przedmiotu sączy się splugawienie.$B$BByć może istnieje związek między nim a smokami, które wyłaniają się ze Snu. Musisz znaleźć kogoś, kto odczyta znaczenie tego przedmiotu. Może druidzi z Gaju Luny albo z Twierdzy Druidów zdołają ci pomóc.', 'Znajdź kogoś, kto zdoła odczytać znaczenie Przedmiotu spowitego koszmarem.$B$BMoże pomoże ci jakiś potężny druid.', '', '', '', '', '', '', 0),
(8447, 'koKR', 'Budzenie legend', 'Wody Jeziora Elune\'ara powinny rozpuścić koszmary spowijające ten przedmiot. Daj mi chwilę na oczyszczenie go, $N.', 'Zaczekaj, aż Opiekun Remulos w Gaju Luny oczyści Przedmiot spowity koszmarem.', 'Budzenie legend.', 'Wróć do Opiekuna Remulosa nad Jeziorem Elune\'ara w Gaju Luny.', '', '', '', '', 0),
(8735, 'koKR', 'Splugawienie koszmaru', 'Musisz udać się do czterech portali snu w Azeroth. Z każdego z nich musisz wydobyć fragment splugawienia koszmaru. Takie fragmenty mają przy sobie smocze istoty zamieszkujące te okolice. Wróć do mnie, gdy je zbierzesz.', 'Udaj się do czterech portali Szmaragdowego Snu w Azeroth i zdobądź z każdego fragment splugawienia koszmaru. Po wykonaniu tego zadania wróć do Opiekuna Remulosa w Gaju Luny.$B', '', 'Wróć do Opiekuna Remulosa nad Jeziorem Elune\'ara w Gaju Luny.', '', '', '', '', 0),
(8736, 'koKR', 'Koszmar się objawia', 'Wobec Eranikusa musimy zachować powściągliwość. Mamy go odkupić, nie zniszczyć.$B$BTyrande jest już w drodze, by pomóc nam w tym zadaniu. Musimy przetrwać ciosy smoka i ocalić Nocny Azyl przed pewną zagładą.$B$BMiej się na baczności! Ty i twoi sojusznicy jesteście naszą jedyną nadzieją.$B', 'Obroń Nocny Azyl przed Eranikusem. Nie pozwól zginąć Opiekunowi Remulosowi. Nie zabijaj Eranikusa. Broń się. Czekaj na Tyrande.$B', 'Odkupienie Eranikusa', 'Wróć do Opiekuna Remulosa przy Kapliczce Remulosa w Gaju Luny.', '', '', '', '', 0),
(8862, 'koKR', 'Świeca Eluny', '', '', '', 'Wróć do Valadara Gwiezdnej Pieśni w Gaju Luny.', '', '', '', '', 0),
(8863, 'koKR', 'Świąteczne pierożki', '', '', '', 'Wróć do Valadara Gwiezdnej Pieśni w Gaju Luny.', '', '', '', '', 0),
(8864, 'koKR', 'Odświętne suknie na Festiwal Księżyca', '', '', '', 'Wróć do Valadara Gwiezdnej Pieśni w Gaju Luny.', '', '', '', '', 0),
(8865, 'koKR', 'Odświętne garnitury na Festiwal Księżyca', '', '', '', 'Wróć do Valadara Gwiezdnej Pieśni w Gaju Luny.', '', '', '', '', 0),
(8868, 'koKR', 'Błogosławieństwo Eluny', 'Omen, dziś bestia, był niegdyś bohaterem tego świata. Wilk o wielkiej sile i szczęściu, walczył u boku bohaterów Wojny Starożytnych, dopóki nie uległ demonicznej magii. Zwróciwszy się przeciw sojusznikom, szalał po całym Azeroth, niosąc ze sobą śmierć i grozę.$B$BPokonany wreszcie tutaj, w Gaju Luny, Omen śpi teraz w mule Jeziora Elune\'ara. Lecz z każdym nowym rokiem, podczas festiwalu, zaczyna się budzić...$B$BZbierz towarzyszy, $N, przyzwij bestię Omena i pokonaj ją. Zasłuż na błogosławieństwo Eluny!', 'Przyzwij Omena, pokonaj go i zdobądź Błogosławieństwo Eluny. Wróć do Valadara Gwiezdnej Pieśni w Nocnym Azylu.', 'Otrzymaj Błogosławieństwo Eluny.', 'Wróć do Valadara Gwiezdnej Pieśni w Nocnym Azylu w Gaju Luny.', '', '', '', '', 0),
(8876, 'koKR', 'Małe rakiety', '', '', '', 'Wróć do Fariel Gwiezdnej Pieśni w Gaju Luny.', '', '', '', '', 0),
(8877, 'koKR', 'Wyrzutnia fajerwerków', '', '', '', 'Wróć do Fariel Gwiezdnej Pieśni w Gaju Luny.', '', '', '', '', 0),
(8878, 'koKR', 'Świąteczne wykroje', '', '', '', 'Wróć do Fariel Gwiezdnej Pieśni w Gaju Luny.', '', '', '', '', 0),
(8879, 'koKR', 'Duże rakiety', '', '', '', 'Wróć do Fariel Gwiezdnej Pieśni w Gaju Luny.', '', '', '', '', 0),
(8880, 'koKR', 'Wiązki rakiet', '', '', '', 'Wróć do Fariel Gwiezdnej Pieśni w Gaju Luny.', '', '', '', '', 0),
(8881, 'koKR', 'Duże wiązki rakiet', '', '', '', 'Wróć do Fariel Gwiezdnej Pieśni w Gaju Luny.', '', '', '', '', 0),
(8882, 'koKR', 'Wyrzutnia wiązek', '', '', '', 'Wróć do Fariel Gwiezdnej Pieśni w Gaju Luny.', '', '', '', '', 0),
(10955, 'koKR', 'Morthis Szeptoskrzydły', 'Zanim wszystkie zakony druidów połączyły się w Krąg Cenariona, to Druidzi Szponu odpowiadali za nauczanie obiecujących młodych druidów tajników latania. Od rozwiązania zakonu jego dawni członkowie rzadko przekazują tę umiejętność.$B$BNawet teraz Morthis Szeptoskrzydły wciąż szuka odpowiedniego ucznia. Niewielu druidów naprawdę opanowało wszystkie dostępne im postacie, ale ty masz w sobie potencjał, jakiego Morthis wymaga od uczniów. Odszukaj go w Schronieniu Cenariona na Moczarach Zangarskich.', 'Odszukaj Morthisa Szeptoskrzydłego w Schronieniu Cenariona na Moczarach Zangarskich.', '', '', '', '', '', '', 0),
(10964, 'koKR', 'Budzenie śpiącego', 'Weź osłonę ze sobą i udaj się do Gaju Luny, do Kurhanów Burzogniewnego. W najbardziej wysuniętym na południe z Kurhanów Burzogniewnego, pod opieką strażników snów, znajdziesz Clintara Wędrowca Snów.$B$BPodaj mu miksturę i czuwaj nad nim, gdy będzie się budził. Będzie bardzo bezbronny, gdy jego duch będzie się łączył z ciałem, i na pewno cię nie rozpozna. Przedstaw mu się, gdy tylko się ocknie, $N. Będzie potrzebował twojej pomocy w zebraniu relikwii na ceremonię.', 'Użyj Osłony przebudzenia, aby pomóc Clintarowi Wędrowcowi Snów wydostać się ze Szmaragdowego Snu. Gdy odzyska przytomność, porozmawiaj z nim.', '', '', '', '', '', '', 0),
(10965, 'koKR', 'To nie tylko sen', '<Clintar słucha, gdy przekazujesz mu polecenia Morthisa; kiwa głową, ale wyraźnie się boi.>$B$BNie mogę całkiem wyrwać się ze Szmaragdowego Snu, by ci pomóc, ale cząstka mojego ducha poprowadzi cię w poszukiwaniu relikwii. Strzeż jej dobrze, $N, bo to krucha rzecz.$B$BSam Szmaragdowy Sen stał się obcym, niebezpiecznym miejscem. Trzyma mnie mocno i nie będę w pełni sobą, dopóki Szmaragdowy Sen nie wróci do normy. To, co widzisz wokół, jest tylko echem rzeczywistości panującej we śnie!', 'Chroń ducha Clintara Wędrowca Snów, gdy będzie zbierał relikwie Aviany, a następnie porozmawiaj ze strażnikiem snów Lurosą.', '', 'Wróć do strażnika snów Lurosy nad Jeziorem Elune\'ara w Gaju Luny.', 'Pomóż Clintarowi zebrać relikwie', '', '', '', 0),
(10978, 'koKR', 'Powrót do Morthisa Szeptoskrzydłego', 'Teraz, gdy relikwie zostały odzyskane, musisz czym prędzej opuścić to miejsce. Clintar zaryzykował swoje bezpieczeństwo i bezpieczeństwo strażników snów, by ci pomóc, $N, ale teraz musi w pełni skupić się na walce z siłą, która najechała Szmaragdowy Sen.$B$BZanieś relikwie Morthisowi Szeptoskrzydłemu razem z wieścią o tym, co tu $gwidziałeś:widziałaś;. Może pomoże nam ustalić, z czym właściwie zmaga się Clintar.', 'Zanieś Relikwie Aviany Morthisowi Szeptoskrzydłemu w Schronieniu Cenariona na Moczarach Zangarskich.', '', '', '', '', '', '', 0),
(13073, 'koKR', 'Przysługa Opiekuna', 'Są na tym świecie istoty, które sięgają po moc nieskrępowaną granicami naszych śmiertelnych ciał – moc odnowy, moc życia i moc światła. A Bridenbrad nie jest zwykłym człowiekiem... jego męstwo i oddanie jaśnieją. Możemy tylko mieć nadzieję, że jedna z tych istot wstawi się za nim i uratuje tego bohatera przed losem gorszym od śmierci.$B$BIdź teraz i porozmawiaj z arcydruidką Lilliandrą w Awangardzie Argentu... poproś o przejście do Gaju Luny i szukaj pomocy Opiekuna Remulosa.', 'Najwyższy lord Tirion Fordring na Szczycie Krzyżowców prosi, byś $guzyskał:uzyskała; od arcydruidki Lilliandry przejście i $gporozmawiał:porozmawiała; z Opiekunem Remulosem w Gaju Luny.', '', '', '', '', '', '', 0),
(13074, 'koKR', 'Nadzieja w Szmaragdowym Koszmarze', 'To, czego potrzebujemy, istnieje tylko w Szmaragdowym Śnie... żołędzie przesycone potężną magią odnowy. Wiele miejsc w tym świętym gaju jest ściśle związanych ze Snem, a moja kapliczka jest jednym z nich.$B$BWyślę cię do Snu, byś $gzdobył:zdobyła; trochę tych żołędzi. Bądź jednak $ggotów:gotowa;, $N, bo ten sposób wejścia do Snu jest niebezpieczny i bardzo możliwe, że dopadną cię koszmary.$B$BSzybko zdobądź kilka żołędzi, a potem oddal się od mojej kapliczki albo się uszczypnij, by wrócić do naszego świata.', 'Opiekun Remulos w Gaju Luny polecił ci wejść do Szmaragdowego Snu i zdobyć 3 szmaragdowe żołędzie.$B$BOddal się od Kapliczki Remulosa, aby wrócić do Azeroth.', '', 'Wróć do Opiekuna Remulosa przy Kapliczce Remulosa w Gaju Luny.', '', '', '', '', 0),
(13075, 'koKR', 'Dar Remulosa', 'Otworzę portal, który zabierze cię z powrotem do druidki, która cię tu przysłała. Tobie i twojemu krzyżowcowi przesyłam najlepsze życzenia. Mam nadzieję, że ten żołądź zdoła oczyścić twojego krzyżowca i uratować go przed nędznym losem zarazy.$B$BBywaj, $N.', 'Wróć ze szmaragdowym żołędziem do krzyżowca Bridenbrada przy Cichym Czuwaniu w Lodowej Koronie.', '', 'Wróć do krzyżowca Bridenbrada przy Cichym Czuwaniu w Lodowej Koronie.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(28, 'koKR', 'No proszę, wygląda na to, że kolejny druid pomyślnie ukończył próbę jeziora! Dobra robota, $gmój młody przyjacielu:moja młoda przyjaciółko; – dobra robota.$B$BJak już mówiłam, nazywam się Tajarri. Moim obowiązkiem i przywilejem jest służba jako strażniczka Gaju Luny, a zwłaszcza tej kapliczki. Opiekun Remulos prowadzi Krąg Cenariona w ochronie natury i równowagi, a jego kapliczka jest trwałym hołdem dla tych wartości. Użycie tutaj błyskotki to ukłon w stronę znaczenia, jakie to miejsce ma dla Kręgu.', 0),
(29, 'koKR', 'No proszę, wygląda na to, że kolejny druid pomyślnie ukończył próbę jeziora! Dobra robota, $gmój młody przyjacielu:moja młoda przyjaciółko; – dobra robota.$B$BJak już mówiłam, nazywam się Tajarri. Moim obowiązkiem i przywilejem jest służba jako strażniczka Gaju Luny, a zwłaszcza tej kapliczki. Opiekun Remulos prowadzi Krąg Cenariona w ochronie natury i równowagi, a jego kapliczka jest trwałym hołdem dla tych wartości. Użycie tutaj błyskotki to ukłon w stronę znaczenia, jakie to miejsce ma dla Kręgu.', 0),
(30, 'koKR', '$GUkończyłeś:Ukończyłaś; próbę lwa morskiego, $N – gratulacje.$B$BKażde zadanie związane ze zdobyciem wisiora pokazuje, że zarówno zwinność, jak i wytrzymałość są niezbędne, by działać w zgodzie z tym, co chcesz zrobić pod wodą. Żadna z nich nie istnieje bez drugiej, a obie są niczym bez twojej gotowości, by przyjąć postać lwa morskiego.$B$BZapamiętaj dobrze te lekcje i polegaj na nich, gdy już zdobędziesz postać morską.', 0),
(272, 'koKR', '$GUkończyłeś:Ukończyłaś; próbę lwa morskiego, $N – gratulacje.$B$BKażde zadanie związane ze zdobyciem wisiora pokazuje, że zarówno zwinność, jak i wytrzymałość są niezbędne, by działać w zgodzie z tym, co chcesz zrobić pod wodą. Żadna z nich nie istnieje bez drugiej, a obie są niczym bez twojej gotowości, by przyjąć postać lwa morskiego.$B$BZapamiętaj dobrze te lekcje i polegaj na nich, gdy już zdobędziesz postać morską.', 0),
(1185, 'koKR', 'Hej, to znowu ty! Znaczy się ty – ty, czyli $N! Tak – właśnie ty!$B$BHej, zacznę od nowa!$B$BTen przedmiot, który $gznalazłeś:znalazłaś; w Silithusie – to była w rzeczywistości książka. Dziennik spisany w bardzo starym dialekcie tego, co dziś nazywamy językiem darnasyjskim. Trochę to potrwa, ale zamierzam go bardzo dokładnie przestudiować. Pomyślałem, że $gpowinieneś:powinnaś; wiedzieć, że to, co $gznalazłeś:znalazłaś;, jest niezwykle cenne dla Kręgu.$B$BNasza matka kwoka jest cała w skowronkach!', 0),
(5526, 'koKR', 'Stało się, $gdzielny:dzielna; $N, i odtąd Krąg Cenariona ma wobec ciebie dług. Choć wojna jeszcze się nie skończyła, wygraliśmy wielką bitwę z tymi, którzy chcieliby sprowadzić na nas zagładę.$b$bProszę – przyjmij to w dowód naszej nieustającej wdzięczności. Wiedz, że za ten wielki czyn zawsze będziesz tu $gmile widziany:mile widziana; jako $gbohater:bohaterka; Kręgu Cenariona, $N. Dziękuję.', 0),
(5527, 'koKR', 'Rzeczywiście jesteś tak $gzaradny:zaradna;, jak wielu twierdzi. Krąg Cenariona ma szczęście, że działasz w naszym imieniu.$b$bGdy relikwiarz znów jest w naszych rękach, mogę odetchnąć. Teraz spokojniej poproszę cię nie tylko o to, byś $gstawił:stawiła; czoła występnemu demonowi, ale też byś $gprzyniósł:przyniosła; przy tym niebezpieczny przedmiot...', 0),
(5929, 'koKR', 'Gdy podchodzisz, Dendrite wykonuje nad sobą kolejny niewidzialny gest. Znów spowija go aura mocy, a on uśmiecha się lekko.$B$B„Wyczuwam w tobie mądrość, $gmłody:młoda;, której nie było, gdy się poznaliśmy. Patrzysz na mnie z siłą i świadomym zamiarem, choć ten zamiar nie jest jeszcze skupiony. Teraz nauczysz się skupiać swoją siłę i wcielać naturę niedźwiedzia w swoje działania”.', 0),
(5930, 'koKR', 'Gdy podchodzisz, Dendrite wykonuje nad sobą kolejny niewidzialny gest. Znów spowija go aura mocy, a on uśmiecha się lekko.$B$B„Wyczuwam w tobie mądrość, $gmłody:młoda;, której nie było, gdy się poznaliśmy. Patrzysz na mnie z siłą i świadomym zamiarem, choć ten zamiar nie jest jeszcze skupiony. Teraz nauczysz się skupiać swoją siłę i wcielać naturę niedźwiedzia w swoje działania”.', 0),
(6845, 'koKR', 'Ach, $N – miałem nadzieję, że zajrzysz. Cieszę się, że widzę cię w dobrym zdrowiu.$b$bDostałem wiadomość, że wracasz z terenu, i chciałem osobiście wyrazić wdzięczność Kręgu Cenariona za dotychczasową pomoc. Z pewnością Silithus kryje jeszcze wiele sekretów, a to, co $gdostarczyłeś:dostarczyłaś; Umberowi, okaże się zapewne niezwykle ciekawe, gdy już zostanie odczytane. Proszę, przyjmij to w dowód naszego nieustającego uznania dla twojej pomocy.$b$bDziękuję ci, $N, za twoją hojność.', 0),
(8446, 'koKR', 'Muszę usunąć skazę z tego przedmiotu. Może to rzuci nieco światła na moje ostatnie nieudane próby wniknięcia do Snu. Daj mi go.', 0),
(8447, 'koKR', 'Weź jego pierścień, $N. Spełnił już swoje zadanie dla Malfuriona. Teraz posłuży nowemu celowi – tobie...', 0),
(8735, 'koKR', 'Czy jesteś $ggotów:gotowa;? Czy świat jest gotów na to, co zamierzamy przywołać? Nie wiem... Wiąże mnie obowiązek wobec Malfuriona. Obowiązek i honor...', 0),
(8736, 'koKR', 'Został odkupiony, $N. Wraca teraz do Snu, by naprawić zło, które sam wyrządził. Eranikus będzie potężnym sojusznikiem Malfuriona i mojego ojca.$b$bTen rynsztunek jest dla ciebie, $N. Dała mi go sama Ysera. Dobrze zrobisz, jeśli użyjesz go w walce z Qiraji.', 0),
(8862, 'koKR', 'Dobrze więc – przyjmuję te monety przodków. Weź, proszę, świecę Eluny wraz z moim błogosławieństwem. Przyjmij też w podarunku te fajerwerki.$B$BNiech twój Festiwal Księżyca będzie radosny i pełen wesela, $N.$B$BA jeśli zechcesz stawić czoła Omenowi i jego sługom, świeca Eluny bardzo ci się przyda...', 0),
(8863, 'koKR', 'Doskonale – częstuj się tymi pierożkami, z wyrazami uznania ode mnie. To tylko skromny dowód uznania za zaszczyt, jaki przynoszą ci twoje czyny, ale myślę, że i tak będą ci smakować.$B$BGdybyś $gmiał:miała; więcej monet przodków, chętnie zaoferuję ci w zamian szeroki wybór przedmiotów.', 0),
(8864, 'koKR', 'Dobrze więc – przyjmuję te monety przodków. Weź, proszę, swoją suknię wraz z moim błogosławieństwem. Przyjmij też w podarunku te fajerwerki.$B$BTak jak ty $guczciłeś:uczciłaś; swoich nestorów, tak mnie zaszczycasz samą swoją obecnością. Dziękuję i niech twój Festiwal Księżyca będzie radosny.', 0),
(8865, 'koKR', 'Dobrze więc – przyjmuję te monety przodków. Weź, proszę, swój garnitur wraz z moim błogosławieństwem. Przyjmij też w podarunku te fajerwerki.$B$BGdybyś $gmiał:miała; więcej monet przodków na wymianę, porozmawiaj ze mną ponownie. Przez cały Festiwal Księżyca będę oferować rozmaite przedmioty.', 0),
(8868, 'koKR', 'Znakomicie, $N. Pokonanie Omena odesłało jego ducha z powrotem do wód Elune\'ara. Choć sama bestia nosi błogosławieństwo Eluny i nie może umrzeć, jej gniew ucichnie na kolejny rok.$b$bTwoje zwycięstwo to święto, $N – święto potęgi Omena, twojej i twoich sojuszników, a także spokoju, jaki $gdałeś:dałaś; temu tragicznemu bohaterowi naszej przeszłości.', 0),
(8876, 'koKR', 'Ach, dobrze. Oto twoje schematy, $N, i niech Eluna cię błogosławi.', 0),
(8877, 'koKR', 'Proszę, $N. Oto schemat wyrzutni fajerwerków. Ustawiaj wyrzutnie tam, gdzie chcesz świętować, a potem zaproś przyjaciół, by do ciebie dołączyli!', 0),
(8878, 'koKR', 'Oto wykroje, $N. Jestem pewna, że to, co dzięki tej wiedzy powstanie, zachwyci cię swoim pięknem.', 0),
(8879, 'koKR', 'Dobrze – przyjmuję te monety przodków. Oto twoje schematy, $N. Obyś dzięki nim $gszerzył:szerzyła; chwałę Eluny!', 0),
(8880, 'koKR', 'Proszę, $N. Weź te schematy i poznaj ich sekrety. Życzę ci szczęścia i nie mogę się doczekać twoich wspaniałych dzieł.', 0),
(8881, 'koKR', 'Dziękuję, $N. Oto schemat dużych wiązek rakiet. Niech twoje wyroby niosą radość i szczęście wszystkim, którzy na nie spojrzą.', 0),
(8882, 'koKR', 'Oto twój schemat. Przestudiuj go uważnie i ucz się...$B$BPowodzenia, $N. Niech twoje uroczystości dorównają samemu Festiwalowi Księżyca!', 0),
(10955, 'koKR', '$GPrzyniosłeś:Przyniosłaś; składniki do wywaru? <Morthis przygląda ci się z pewnym sceptycyzmem.>$B$BOd dawna szukam ucznia, któremu mógłbym przekazać swoją wiedzę. Choć Druidzi Szponu nie są już formalną grupą, ja pozostanę jednym z nich do końca swoich dni.$B$BOd tej chwili przyjmuję cię na ucznia. Ja nauczę cię sekretów burzowej wrony. Ty zaś musisz być $ggotów:gotowa; zrobić wszystko, o co poproszę. Rozumiesz?', 0),
(10964, 'koKR', '<Druid budzi się ze snu, oszołomiony i wymizerowany. Jego wzrok błądzi po komnacie w poszukiwaniu niewidzialnych prześladowców.>$B$BMorthis?$B$BNie, nie jesteś Morthisem... Kim jesteś, $N, i dlaczego zakłócasz mój spoczynek?$B$B<Mimo wrogości pytania druid wygląda niemal na zadowolonego, że go obudzono.>', 0),
(10965, 'koKR', 'Masz szczęście, że Clintar był na tyle silny, by tak długo utrzymać rozszczepienie swojej esencji, $N. Niewielu druidów potrafi dokonać czegoś takiego, będąc atakowanym w Szmaragdowym Śnie. Strzeż relikwii dobrze!', 0),
(10978, 'koKR', '<Morthis przyjmuje od ciebie relikwie, gdy opowiadasz o tym, co $gprzeżyłeś:przeżyłaś; w kurhanach.>$B$BTo bardzo niepokojące wieści, $N. W Szmaragdowym Śnie dochodziło do wielu dziwnych zakłóceń, ale nie przypominam sobie żadnej wzmianki o tym, by ingerowały w niego siły z zewnątrz. Czy na pewno Clintar tak uważa?', 0),
(13073, 'koKR', 'Witaj, dziecko.$B$BRozumiem prośbę Tiriona i ufam jego osądowi. Zobaczymy, co da się zrobić dla tego krzyżowca Bridenbrada. Prosisz o coś niełatwego – Plaga nie pochodzi z tego świata i przez lata wielu nie zdołało usunąć jej splugawienia.$B$BLecz w istocie szlachetnej i pełnej światła nie wszystko jest stracone.', 0),
(13074, 'koKR', 'Świetna robota, $gmłody:młoda;.', 0),
(13075, 'koKR', 'Tirion wysłał cię do Remulosa? Ja... Pochlebia mi to. Nie prosi się o przysługi istot o takiej mocy bez powodu, choćby były nie wiem jak szlachetne i bezinteresowne. Ty również okazujesz wielką dobroć, zadając sobie tyle trudu w mojej sprawie. Dziękuję ci.$B$BZasadź nasiono – jestem gotów.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(30, 'koKR', '$GZłożyłeś:Złożyłaś; wisior, żebym mógł go obejrzeć, $N? Jeśli potrzebujesz pomocy w odnalezieniu części, popytaj miejscowych. Nie tylko znajdziesz to, czego szukasz, ale też zyskasz powód, by zwiedzić ten cudowny, święty gaj.', 0),
(272, 'koKR', '$GZłożyłeś:Złożyłaś; wisior, żebym mógł go obejrzeć, $N? Jeśli potrzebujesz pomocy w odnalezieniu części, popytaj miejscowych. Nie tylko znajdziesz to, czego szukasz, ale też zyskasz powód, by zwiedzić ten cudowny, święty gaj.', 0),
(5526, 'koKR', 'Mając w posiadaniu zapieczętowany relikwiarz czystości, nie tylko usuniemy ze świata splugawiające zagrożenie, ale też będziemy mogli je badać pod naszym czujnym okiem. Może nawet wymyślimy nowe sposoby walki ze skazą splugawienia, która nieustannie zagraża Azeroth.$b$bWiem, że Milli nie chciałaby, żeby było inaczej...', 0),
(5527, 'koKR', 'Relikwiarz czystości to artefakt sam w sobie. Powstało ich niewiele i uważano, że niemal wszystkie z czasem zaginęły.$B$BPrzyznaję, że o tym w Południowym Wietrze wiem już od jakiegoś czasu. Szczerze mówiąc, przy narastającym zamęcie w Silithusie wolałem, żeby nasze sekrety pozostały sekretami. Węszenie i grzebanie tylko wzbudziłoby podejrzenia naszych wrogów.$B$BNiestety czas bezczynności dobiegł końca, zwłaszcza przy tym, co dzieje się w Eldre\'Thalas.', 0),
(8735, 'koKR', '<Remulos jest pogrążony w myślach.>', 0),
(8862, 'koKR', 'Świeca Eluny to artefakt otaczany wielką czcią przez świętujących Festiwal Księżyca. W świecy zamknięte jest prawdziwe światło księżyca, gotowe, by je uwolnić!$b$bDla większości stworzeń to światło jest nieszkodliwe, ale przekonasz się, że Omena i jego sługi pali ono i oślepia.', 0),
(8864, 'koKR', 'Mam wybór sukien, które mogą cię zainteresować. Takie suknie noszono dawniej podczas Festiwalu Księżyca, a te, które mam dzisiaj, są chyba najpiękniejsze, jakie w życiu widziałem. Każda jest uszyta ręcznie z najlepszych i najdelikatniejszych materiałów.$B$BW zamian za kilka monet przodków pozwolę ci wybrać na własność jeden z trzech krojów, które mam. Odpowiada ci to?', 0),
(8865, 'koKR', 'Z przyjemnością informuję, że mam dla ciebie piękny wybór odświętnych garniturów... ale tylko w zamian za monety przodków. Jeśli zależy ci na modzie, to właśnie tego szukasz! Zapewniam, że takich garniturów nie znajdziesz nigdzie indziej.$B$BW zamian za kilka monet przodków pozwolę ci wybrać na własność jeden z trzech krojów, które mam. Odpowiada ci to?', 0),
(8881, 'koKR', 'Duże wiązki rakiet wymagają ogromnych zasobów i wielkiej wprawy, ale ich blask i piękno są warte tego wysiłku! Przynieś mi monety przodków, a przekażę ci wiedzę o ich konstruowaniu.', 0),
(8882, 'koKR', 'Najwspanialsze pokazy fajerwerków nie mogą się obyć bez wiązek rakiet, a wiązki rakiet trzeba odpalać z wyrzutni wiązek! Czyż nie jest więc logiczne, byś $gpoznał:poznała; sekrety budowy wyrzutni wiązek? Przynieś mi monety przodków, a przekażę ci tę wiedzę.', 0),
(10964, 'koKR', '<Przygotowujesz się do podania mikstury śpiącemu druidowi.>', 0),
(10965, 'koKR', 'Pospiesz się, $N. Jeśli te stwory wydostaną się z kurhanu, w niebezpieczeństwie będzie nie tylko Clintar Wędrowiec Snów.', 0),
(10978, 'koKR', 'Czy Clintar pomógł ci odzyskać relikwie?', 0),
(13074, 'koKR', 'Dobrze widzieć, że nic ci nie jest. Masz żołędzie?', 0),
(13075, 'koKR', 'Witaj, $N. Wiedziałem, że wrócisz mimo moich ostrzeżeń, ale cieszę się, że $guszanowałeś:uszanowałaś; moje życzenie, by nie narażać nikogo innego.$B$BCzemu do mnie $gwróciłeś:wróciłaś;?', 0);
