INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(7437, 'koKR', 'Niedźwiedź patrzy na ciebie spokojnie i cierpliwie, ale nic nie mówi.', '', 0),
(7438, 'koKR', 'Duch niedźwiedzia spogląda na ciebie spokojnym, łagodnym wzrokiem. Słyszysz głos, który zdaje się dochodzić od niedźwiedzia, choć nic nie wskazuje na to, by stworzenie mówiło.$B$B„Witaj, $gmój młody przyjacielu:moja młoda przyjaciółko;. Jeśli przychodzisz do mnie po radę, może pomogę ci odnaleźć to, czego szukasz”.', '', 0),
(7439, 'koKR', 'Co uosabiasz, duchu?', 'Co uosabiasz, duchu?', 0),
(7441, 'koKR', 'Uosabiam siłę, która wspiera cię jako $gmłodego druida:młodą druidkę;. $GPrzyszedłeś:Przyszłaś; do mnie, by poznać tę siłę, $gmłody:młoda;, a ja cię jej nauczę. Nauczę cię wszystkiego, czym jest duch niedźwiedzia, o ile będziesz słuchać i rozumieć.$B$BAby wiedzieć, co znaczy czerpać z mojego ducha, musisz zrozumieć, jak ważna jest siła ciała, a także siła serca.', '', 0),
(7442, 'koKR', 'Pragnę zrozumieć, jak ważna jest siła ciała.', 'Pragnę zrozumieć, jak ważna jest siła ciała.', 0),
(7443, 'koKR', 'Siła ciała to moc i szybkość działania. Musisz zawsze dbać o sprawność – zarówno fizyczną, jak i umysłową. Potężna postura niedźwiedzia podkreśla jego siłę, bo w walce jest groźnym przeciwnikiem. Ta sama postura skrywa jednak jego gibką zwinność i bystry umysł. Te niespodzianki obrócisz na swoją korzyść.$B$BMusisz polegać na sile niedźwiedziego ciała, by opanować drogę Pazura.', '', 0),
(7444, 'koKR', 'Pragnę zrozumieć, jak ważna jest siła serca.', 'Pragnę zrozumieć, jak ważna jest siła serca.', 0),
(7445, 'koKR', 'Siła serca daje ci determinację do działania... działania zakorzenionego w czystych i szczerych zamiarach. Utrzymywanie równowagi nie oznacza bierności ani banalności.$B$BMusisz wykazać się determinacją w obronie tego, w co wierzysz, i musisz być $ggotów:gotowa; o to walczyć. Niedźwiedzica okazuje niezłomne przekonanie, broniąc swoich młodych, podobnie jak stary niedźwiedź broniący swojej gawry. To tę determinację, tę siłę serca musisz poznać, jeśli chcesz opanować drogę Pazura.', '', 0),
(7446, 'koKR', '$GWysłuchałem:Wysłuchałam; twoich słów, Duchu Wielkiego Niedźwiedzia, i rozumiem. Teraz proszę cię o błogosławieństwo, bym $gmógł:mogła; w pełni poznać drogę Pazura.', '$GWysłuchałem:Wysłuchałam; twoich słów, Duchu Wielkiego Niedźwiedzia, i rozumiem. Teraz proszę cię o błogosławieństwo, bym $gmógł:mogła; w pełni poznać drogę Pazura.', 0),
(7447, 'koKR', 'Okaże się, czy jesteś $ggotów:gotowa;, $gmłody druidzie:młoda druidko;. Nawet najmądrzejsi i najstarsi z druidów nigdy nie są naprawdę gotowi, gdy nadchodzi ich ostateczna próba.$B$B$GWysłuchałeś:Wysłuchałaś; moich słów, a teraz musisz ruszać dalej. Pamiętaj, czego cię nauczyłem. Nadejdzie czas, gdy twoja siła zostanie wystawiona na próbę. Musisz stawić czoła wrogowi tak, jak zrobiłby to niedźwiedź – z siłą ciała i siłą serca. Ucz się z walki, $gmłody druidzie:młoda druidko;. Idź... z moim błogosławieństwem.', '', 0),
(7572, 'koKR', '', 'Nie jesteś $gdruidem:druidką;!', 0),
(7573, 'koKR', 'Chcę polecieć do Wioski Rut\'theran.', 'Chcę polecieć do Wioski Rut\'theran.', 0),
(7574, 'koKR', '', 'Chcesz polecieć do Wioski Rut\'theran dzięki uprzejmości Kręgu Cenariona?', 0),
(7575, 'koKR', '', 'Jeśli szukasz lotu z powrotem do Gromowych Urwisk, porozmawiaj z moim taureńskim odpowiednikiem, Bunthenem Wiatrem Równin.', 0),
(7576, 'koKR', 'Nie jesteś $gdruidem:druidką;!', '', 0),
(7577, 'koKR', 'Chcesz polecieć do Gromowych Urwisk dzięki uprzejmości Kręgu Cenariona?', '', 0),
(7578, 'koKR', 'Jeśli szukasz lotu z powrotem do Wioski Rut\'theran, porozmawiaj z moją nocnoelfią odpowiedniczką, Silvą Fil\'naveth.', '', 0),
(7618, 'koKR', '', 'Kapliczka Remulosa to dla nas, członków Kręgu Cenariona tu, w Gaju Luny, święte miejsce... więc zachowuj się, proszę, jak przystoi gościowi.$B$BGościowi, który nie chce skończyć z moim sejmitarem w brzuchu, rzecz jasna.', 0),
(8035, 'koKR', 'Wiesz może, gdzie znajdę połowę wisiora wodnej zręczności?', 'Wiesz może, gdzie znajdę połowę wisiora wodnej zręczności?', 0),
(8036, 'koKR', 'Wiesz może, gdzie znajdę połówkę wisiora wodnej wytrzymałości?', 'Wiesz może, gdzie znajdę połówkę wisiora wodnej wytrzymałości?', 0),
(11659, 'koKR', '', 'Ja, tak jak mój brat, szanuję tych, którzy czczą swoich przodków. Z wielką radością dzielę się sekretami mojego rzemiosła ze świętującymi Festiwal Księżyca!', 0),
(12804, 'koKR', 'Chcę polecieć do Gromowych Urwisk.', 'Chcę polecieć do Gromowych Urwisk.', 0),
(20471, 'koKR', '<Morthis spogląda w niebo.>$B$BW pewnym sensie zazdroszczę Rookowi i Corvaxowi ich wolności. Być wolnym od ziemskich obowiązków to zaiste wielkie błogosławieństwo.$B$BW przyszłości znów wzbiję się w powietrze, ale najpierw muszę wykonać pewne zadanie.', '', 0),
(20512, 'koKR', '%s klęka i napełnia fiolkę wodą z księżycowej studni.', '', 0),
(20513, 'koKR', 'Mikstura gotowa. Mogę tylko mieć nadzieję, że Clintar wybaczy nam przerwanie jego pobytu w Szmaragdowym Śnie.', '', 0),
(20516, 'koKR', 'Niewielu już na świecie potrafi przygotować Osłonę przebudzenia, $n. Na szczęście jestem jednym z nich.', '', 0),
(20517, 'koKR', '%s łączy zioła z wodą z księżycowej studni, tworząc Osłonę przebudzenia.', '', 0),
(20523, 'koKR', '%s gwałtownie podrywa się do klęku, ale wydaje się nieobecny.', '', 0),
(20524, 'koKR', 'Co robisz w królestwie Ysery, intruzie? Odejdź, mówię! Twoi pobratymcy nie są tu mile widziani!', '', 0),
(20525, 'koKR', '%s wstaje i zaczyna rozpoznawać otoczenie.', '', 0),
(20532, 'koKR', 'Idą za mną, $N! Szybko, powiedz mi, po co tu jesteś, zanim nas odkryją! Jeśli mnie dopadną, będzie to oznaczać moją i twoją śmierć!', '', 0),
(20535, 'koKR', '<Druid wydaje się pogrążony w głębokim śnie, nieświadomy otoczenia.>', '', 0),
(20538, 'koKR', 'Ty... ty nie jesteś jednym z nich! Schowajmy się, zanim nas znajdą! Szybko!', '', 0),
(20601, 'koKR', 'Lurosa, powierzam Relikwie Aviany $n, $gktóry:która; zaniesie je Morthisowi Szeptoskrzydłemu. Muszę teraz całkowicie wrócić do Szmaragdowego Snu. Nie pozwól, by $n $gzawiódł:zawiodła;!', '', 0),
(31592, 'koKR', 'Zdobycie Szczytu Krzyżowców to dopiero pierwszy krok długiej i niebezpiecznej podróży. Wiele jeszcze trzeba zrobić, zanim będziemy mogli zaatakować Cytadelę Lodowej Korony.$B$BBędzie to możliwe tylko dzięki pomocy twojej i takich jak ty, $gbohaterze:bohaterko;.', '', 0);
